import { useEffect, useState } from "react";
import { callAPI } from "../utils/apiUtils";
import { apiUrls } from "../utils/apiUrls";
import { SelectBoxLoader } from "./common";

export default function GetAllOptions({
  value = [],
  fn,
  load,
  name = "optionTypeId",
  disabled = false,
  className = null,
  producttypeId = "",
  indexId = 0,
}) {

  const [optionList, setoptionList] = useState([]);
  const [allOption, setAllOption] = useState([]);
  const [show, setShow] = useState(false);

  const optionlist = async () => {
    try {
      if (!producttypeId) return;
      setShow(true);
      let query = { productId: producttypeId };
      const apiResponse = await callAPI(apiUrls.GetAllOption, query, "GET", {});
      setShow(false);
      if (apiResponse?.data?.isSuccess) {
        const fetchedOptions = apiResponse?.data?.data;
        setoptionList(fetchedOptions);
        const defaultOptions = fetchedOptions.reduce((acc, item) => {
          const defaults = item?.options
            .filter((option) => option.isDefault)
            .map((option) => ({
              optionName: item?.optionId + "-" + indexId,
              value: option?.optionTypeId,
            }));
          return [...acc, ...defaults];
        }, []);
        setAllOption(defaultOptions);
      } else {
        setoptionList([]);
        setAllOption([]);
      }
    } catch (error) {
      setShow(false);
      setoptionList([]);
      setAllOption([]);
    }
  };

  useEffect(() => {
    setoptionList([]);
    setAllOption([]);
    if (producttypeId) {
      optionlist();
    }
    // eslint-disable-next-line
  }, [producttypeId, load]);

  useEffect(() => {
    if (fn) {
      fn({ target: { name, value: allOption.map((obj) => obj.value) } });
    }
    // eslint-disable-next-line
  }, [allOption, name]);

  const handleChangeOption = (e, optionName, optionId) => {
    setAllOption((prevOptions) => {
      return prevOptions.map((opt) =>
        opt.optionName === `${optionName}-${indexId}`
          ? { ...opt, value: e.target.value }
          : opt
      );
    });
  };

  return (
    <div className="position-relative">
      {show && <SelectBoxLoader />}

      <div>
        {optionList?.map((item, i) => (
          <div key={i} className="d-flex gap-3">
            <label
              className="form-check-label font-14 bold-label"
              htmlFor={`flexCheck-${item?.optionId}`}
            >
              {item?.optionName}
            </label>
            <div className="d-flex gap-3 flex-wrap">
              {item?.options.map((option, index) => (
                <div className="form-check" key={index}>
                  <input
                    className="form-check-input"
                    type="radio"
                    id={`flexCheck-${option?.optionTypeId}-${indexId}`}
                    name={`${item?.optionId}-${indexId}`} // Unique group per option set
                    value={option?.optionTypeId}
                    checked={allOption.some(
                      (opt) =>
                        opt.optionName === `${item?.optionId}-${indexId}` &&
                        opt.value === option?.optionTypeId
                    )}
                    onChange={(e) =>
                      handleChangeOption(
                        e,
                        item?.optionId,
                        option?.optionTypeId
                      )
                    }
                    disabled={disabled}
                  />
                  <label
                    className="form-check-label"
                    htmlFor={`flexCheck-${option?.optionTypeId}-${indexId}`}
                  >
                    {option?.optionType}
                  </label>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
